mapper.select:
WITH q AS ( SELECT websearch_to_tsquery('public.wsb_zhcfg', #{query}) AS ts_query, #{pattern} AS pattern ), raw AS ( SELECT (metadata->>'bookId')::bigint AS book_id, coalesce(nullif(metadata->>'canonicalBookKey', ''), 'BOOK:' || metadata->>'bookId') AS canonical_key, ts_rank_cd(to_tsvector('public.wsb_zhcfg', coalesce(content, '')), q.ts_query) + CASE WHEN content ILIKE q.pattern ESCAPE '\' THEN 0.50 ELSE 0 END + CASE WHEN metadata->>'title' ILIKE q.pattern ESCAPE '\' THEN 1.20 ELSE 0 END + CASE WHEN metadata->>'author' ILIKE q.pattern ESCAPE '\' THEN 1.00 ELSE 0 END + CASE WHEN metadata->>'keyword' ILIKE q.pattern ESCAPE '\' THEN 0.90 ELSE 0 END + CASE WHEN metadata->>'clcCategory' ILIKE q.pattern ESCAPE '\' THEN 0.75 ELSE 0 END + CASE WHEN metadata->>'clc' ILIKE q.pattern ESCAPE '\' THEN 0.70 ELSE 0 END
+ CASE WHEN content ILIKE #{queryPattern} ESCAPE '\' THEN 0.20 ELSE 0 END + CASE WHEN metadata->>'title' ILIKE #{queryPattern} ESCAPE '\' THEN 0.55 ELSE 0 END + CASE WHEN metadata->>'author' ILIKE #{queryPattern} ESCAPE '\' THEN 0.45 ELSE 0 END + CASE WHEN metadata->>'keyword' ILIKE #{queryPattern} ESCAPE '\' THEN 0.40 ELSE 0 END + CASE WHEN metadata->>'clcCategory' ILIKE #{queryPattern} ESCAPE '\' THEN 0.35 ELSE 0 END + CASE WHEN metadata->>'clc' ILIKE #{queryPattern} ESCAPE '\' THEN 0.30 ELSE 0 END
+ (coalesce(nullif(metadata->>'chunkWeight', ''), '1')::double precision * 0.05) AS row_score FROM ${tableName}, q WHERE metadata->>'bookId' IS NOT NULL
AND (metadata->>'bookId')::bigint IN
#{bookId}
AND ( q.ts_query @@ to_tsvector('public.wsb_zhcfg', coalesce(content, '')) OR content ILIKE q.pattern ESCAPE '\' OR metadata->>'title' ILIKE q.pattern ESCAPE '\' OR metadata->>'author' ILIKE q.pattern ESCAPE '\' OR metadata->>'keyword' ILIKE q.pattern ESCAPE '\' OR metadata->>'clcCategory' ILIKE q.pattern ESCAPE '\' OR metadata->>'clc' ILIKE q.pattern ESCAPE '\'
OR content ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'title' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'author' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'keyword' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'clcCategory' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'clc' ILIKE #{queryPattern} ESCAPE '\'
) ), deduped AS ( SELECT canonical_key, MAX(row_score) AS rank_score FROM raw GROUP BY canonical_key ) SELECT r.book_id, d.rank_score FROM deduped d JOIN LATERAL ( SELECT r2.book_id FROM raw r2 WHERE r2.canonical_key = d.canonical_key ORDER BY r2.book_id DESC LIMIT 1 ) r ON true ORDER BY d.rank_score DESC LIMIT #{limit}
